import java.util.Scanner;

public class Main {
    public static int findGCD(int a, int b) {
        int gcdValue = Math.max(a, b);
        while (true) {
            if (a % gcdValue == 0 && b % gcdValue == 0)
                return gcdValue;
            gcdValue--;
        }
    }

    public static void computeDiff(double x, double y, double a, double b, double[] result) {
        result[0] = Math.abs(x * b - y * a);
        result[1] = y * b;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        if (n > y) {
            int g = findGCD((int) x, (int) y);
            if (g != 1) {
                x /= g;
                y /= g;
            }
            System.out.println((x) + "/" + (y));
            return;
        }

        double minRatio = 1e9;
        int bestNum = 0;
        int bestDen = 0;

        for (double b = n; b >= 1; b--) {
            double a = (x * b) / y;
            if (Math.floor(a) == a) {
                bestNum = (int) a;
                bestDen = (int) b;
                break;
            } else {
                double[] diffResult = new double[2];

                computeDiff(x, y, Math.floor(a), b, diffResult);
                double num = diffResult[0];
                double den = diffResult[1];
                double ratio = num / den;

                if (ratio < minRatio) {
                    minRatio = ratio;
                    bestNum = (int) Math.floor(a);
                    bestDen = (int) b;
                } else if (ratio == minRatio && (int) Math.floor(a) < bestNum) {
                    bestNum = (int) Math.floor(a);
                    bestDen = (int) b;
                }

                computeDiff(x, y, Math.ceil(a), b, diffResult);
                num = diffResult[0];
                den = diffResult[1];
                ratio = num / den;

                if (ratio < minRatio) {
                    minRatio = ratio;
                    bestNum = (int) Math.ceil(a);
                    bestDen = (int) b;
                } else if (ratio == minRatio && (int) Math.ceil(a) < bestNum) {
                    bestNum = (int) Math.ceil(a);
                    bestDen = (int) b;
                }
            }
        }

        int g = findGCD(bestNum, bestDen);
        if (g != 1) {
            bestNum /= g;
            bestDen /= g;
        }
        System.out.println(bestNum + "/" + bestDen);
    }
}
